const test = require('node:test');
const assert = require('node:assert/strict');
const { resolveAsset } = require('../src/asset-link.cjs');

test("base directory depends on its final slash", () => {
  assert.equal(resolveAsset('cover.png', 'https://cdn.harbor.example/gallery/index.html'), 'https://cdn.harbor.example/gallery/cover.png');
  assert.equal(resolveAsset('cover.png', 'https://cdn.harbor.example/gallery/'), 'https://cdn.harbor.example/gallery/cover.png');
  assert.equal(resolveAsset('cover.png', 'https://cdn.harbor.example/gallery'), 'https://cdn.harbor.example/cover.png');
});

test("parent root and absolute references", () => {
  const base = 'https://cdn.harbor.example/gallery/2026/index.html';
  assert.equal(resolveAsset('../thumb.png', base), 'https://cdn.harbor.example/gallery/thumb.png');
  assert.equal(resolveAsset('/brand.svg', base), 'https://cdn.harbor.example/brand.svg');
  assert.equal(resolveAsset('https://media.harbor.example/logo.svg', base), 'https://media.harbor.example/logo.svg');
});

test("invalid relative resolution propagates TypeError", () => {
  assert.throws(() => resolveAsset('cover.png'), TypeError);
  assert.throws(() => resolveAsset('/cover.png', ''), TypeError);
});

test("absolute references work without a base", () => {
  assert.equal(resolveAsset('https://media.harbor.example/a b.svg?mode=full#icon'), 'https://media.harbor.example/a%20b.svg?mode=full#icon');
});

